import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { API, graphqlOperation } from "aws-amplify";
import { create_list_nominations } from "@/graphql/mutations.js";
export default {
  name: "RequestAdvanceDialog",
  mixins: [get_all_org_users],
  props: {
    userNomination: {
      type: Boolean,
      required: true
    }
  },
  data() {
    return {
      loading: false,
      userLoading: false,
      userItems: [],
      rewardTitle: "",
      userDescription: "",
      userNominated: ""
    };
  },
  watch: {
    userNomination: {
      async handler() {
        if (this.userNomination == true) {
          this.$store.commit("Setnamesearch", "");
          this.userLoading = true;
          await this.get_all_org_users();
          await this.fetchData();
          this.userLoading = false;
        }
      },
      immediate: true
    }
  },
  methods: {
    fetchData() {
      this.userItems = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userItems.push({
            full_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
      this.userLoading = false;
      // console.log(this.orgUsers);
    },
    async submitAdvanceRequest() {
      const {
        valid
      } = await this.$refs.form1.validate();
      // console.log(valid);
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(create_list_nominations, {
            input: {
              nominee_email_id: this.userNominated,
              recommendation_title: this.rewardTitle,
              recommendation_description: this.userDescription,
              action_type: "CREATE_NOMINATION"
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.create_list_nominations);
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.resetForm();
            this.$emit("clicked");
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          console.log(error);
          this.loading = false;
          this.$emit("errorMsg", error.errors?.[0]?.message || error.message);
        }
      }
    },
    closeDialog() {
      this.resetForm();
      this.$emit("clicked");
    },
    resetForm() {
      this.userNominated = "";
      this.rewardTitl = "";
      this.userDescription = "";
    }
  }
};
